function onClick(event){const button=event.target.closest('button'),cell=event.target.closest('[data-aw-cell]');if(!allowed()||identityOf()!==identity){reset();return;}if(button){if(button.disabled)return;if(button.dataset.awSheet){void selectSheet(button.dataset.awSheet);return;}if(button.dataset.awFilter){const [table,col]=JSON.parse(button.dataset.awFilter);openFilter(table,col);return;}if(button.id==='aw-bandwidth-go'){jumpBandwidth();return;}if(button.id==='aw-bandwidth-details'){openPurchaseDetails();return;}if(button.id==='aw-refresh'){void load(activeName);return;}if(button.id==='aw-edit-cell'){openCellEditor();return;}if(button.id==='aw-clear-filters'){for(const [key,value]of filters)if(value.sheet===activeName)filters.delete(key);clearSourceFilters=true;void load(activeName);return;}if(button.id==='aw-check-status')void checkStatus();if(button.id==='aw-resume')void continueOriginal(true);if(button.id==='aw-retry-original')void continueOriginal(false);if(button.id==='aw-review-release')openRelease();return;}if(cell)selectCell(cell.dataset.awCell);}
